
CREATE DATABASE IF NOT EXISTS fatturazioni;
USE fatturazioni;
SET NAMES utf8mb4;

-- 0 = conserva tutti i dati preesistenti; 1 = sostituisce i soli segnaposto
-- corrispondenti ai modelli esatti della precedente versione dello script.
SET @pop_aggiorna_vecchi_test = 0;

CREATE TABLE IF NOT EXISTS cliente (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(255) NOT NULL,
    cognome VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS domicilio (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    via VARCHAR(255) NOT NULL,
    citta VARCHAR(255) NOT NULL,
    cap VARCHAR(255) NOT NULL,
    civico VARCHAR(255)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS domicili_cliente (
    id_cliente BIGINT NOT NULL,
    id_domicilio BIGINT NOT NULL,
    PRIMARY KEY (id_cliente, id_domicilio),
    CONSTRAINT fk_domicili_cliente_cliente
        FOREIGN KEY (id_cliente) REFERENCES cliente(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_domicili_cliente_domicilio
        FOREIGN KEY (id_domicilio) REFERENCES domicilio(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS fatturazione (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    codice VARCHAR(255) NOT NULL UNIQUE,
    dataEmissione DATE NOT NULL,
    importo DOUBLE NOT NULL,
    dataScadenza DATE NOT NULL,
    tipologia VARCHAR(255) NOT NULL,
    id_domicilio BIGINT NOT NULL,
    CONSTRAINT fk_fatturazione_domicilio
        FOREIGN KEY (id_domicilio) REFERENCES domicilio(id)
        ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS pagamento (
    id_fatturazione BIGINT NOT NULL,
    id_cliente BIGINT NOT NULL,
    dataPagamento DATE NOT NULL,
    PRIMARY KEY (id_fatturazione, id_cliente),
    CONSTRAINT fk_pagamento_fatturazione
        FOREIGN KEY (id_fatturazione) REFERENCES fatturazione(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_pagamento_cliente
        FOREIGN KEY (id_cliente) REFERENCES cliente(id)
        ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

-- Solo tabelle temporanee della connessione corrente: nessuna tabella permanente
-- viene eliminata. Questo permette anche di ripartire nella stessa connessione.
DROP TEMPORARY TABLE IF EXISTS tmp_pop_numeri;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_nomi;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_cognomi;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_indirizzi;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_clienti;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_domicili;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_fatture;

START TRANSACTION;

-- Numeri da 1 a 100.000, senza ricorsione né procedure memorizzate.
CREATE TEMPORARY TABLE tmp_pop_numeri (
    n INT NOT NULL PRIMARY KEY
) ENGINE=InnoDB;

SELECT 1 + a.n + 10*b.n + 100*c.n + 1000*d.n + 10000*e.n
FROM (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) AS a
CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) AS b
CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) AS c
CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) AS d
CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) AS e;

-- Elenchi di appoggio incorporati nello script, senza download o CSV esterni.
CREATE TEMPORARY TABLE tmp_pop_nomi (
    progressivo INT NOT NULL PRIMARY KEY,
    nome VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TEMPORARY TABLE tmp_pop_cognomi (
    progressivo INT NOT NULL PRIMARY KEY,
    cognome VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;




CREATE TEMPORARY TABLE tmp_pop_indirizzi (
    progressivo INT NOT NULL PRIMARY KEY,
    via VARCHAR(255) NOT NULL,
    citta VARCHAR(255) NOT NULL,
    cap VARCHAR(5) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;







































































-- Le combinazioni di nome e cognome sono generate in modo deterministico.
-- Gli indirizzi pubblici vengono riutilizzati solo dopo aver percorso la lista.
-- Aggiornamento facoltativo dei segnaposto della vecchia versione. I confronti
-- binari e la verifica di tutti i campi riducono il rischio di toccare record
-- diversi; non costituiscono però una prova dell'origine di quei record.
UPDATE cliente AS c
INNER JOIN tmp_pop_numeri AS n
    ON n.n = CASE
        WHEN c.nome REGEXP '^Nome test [1-9][0-9]{0,5}$'
        THEN CAST(SUBSTRING(c.nome, 11) AS UNSIGNED) ELSE NULL END
    AND BINARY c.nome = BINARY CONCAT('Nome test ', n.n)
    AND BINARY c.cognome = BINARY CONCAT('Cognome test ', n.n)
INNER JOIN tmp_pop_nomi AS nomi
    ON nomi.progressivo = 1 + MOD((n.n - 1) * 3571, 458)
INNER JOIN tmp_pop_cognomi AS cognomi
    ON cognomi.progressivo = 1 + MOD(FLOOR((n.n - 1) * 3571 / 458), 1164)
SET c.nome = nomi.nome, c.cognome = cognomi.cognome
WHERE @pop_aggiorna_vecchi_test = 1;

UPDATE domicilio AS d
INNER JOIN tmp_pop_numeri AS n
    ON n.n = CASE
        WHEN d.via REGEXP '^Via di prova [1-9][0-9]{0,5}$'
        THEN CAST(SUBSTRING(d.via, 14) AS UNSIGNED) ELSE NULL END
    AND BINARY d.via = BINARY CONCAT('Via di prova ', n.n)
    AND BINARY d.citta = BINARY CONCAT('Citta di prova ', 1 + MOD(n.n - 1, 100))
    AND BINARY d.cap = BINARY LPAD(MOD(n.n - 1, 100000), 5, '0')
    AND BINARY d.civico = BINARY CAST(1 + MOD(n.n - 1, 200) AS CHAR)
INNER JOIN tmp_pop_indirizzi AS indirizzi
    ON indirizzi.progressivo = 1 + MOD(n.n - 1, 34675)
SET d.via = indirizzi.via, d.citta = indirizzi.citta,
    d.cap = indirizzi.cap, d.civico = NULL
WHERE @pop_aggiorna_vecchi_test = 1;

-- 1. Clienti: gli ID sono assegnati da AUTO_INCREMENT.
SELECT 100000 - LEAST(100000, COUNT(*)) INTO @pop_clienti_mancanti
FROM cliente;

SELECT nomi.nome, cognomi.cognome
FROM tmp_pop_numeri AS n
INNER JOIN tmp_pop_nomi AS nomi
    ON nomi.progressivo = 1 + MOD((n.n - 1) * 3571, 458)
INNER JOIN tmp_pop_cognomi AS cognomi
    ON cognomi.progressivo = 1 + MOD(FLOOR((n.n - 1) * 3571 / 458), 1164)
WHERE n.n <= @pop_clienti_mancanti
ORDER BY n.n;

-- 2. Domicili: anche in questo caso non si presume che gli ID siano continui.
SELECT 100000 - LEAST(100000, COUNT(*)) INTO @pop_domicili_mancanti
FROM domicilio;

SELECT indirizzi.via, indirizzi.citta, indirizzi.cap, NULL
FROM tmp_pop_numeri AS n
INNER JOIN tmp_pop_indirizzi AS indirizzi
    ON indirizzi.progressivo = 1 + MOD(n.n - 1, 34675)
WHERE n.n <= @pop_domicili_mancanti
ORDER BY n.n;

-- Mappe ordinate dei primi 100.000 ID realmente presenti. Il progressivo serve
-- soltanto all'interno dello script e non altera le tabelle originali.
CREATE TEMPORARY TABLE tmp_pop_clienti (
    progressivo INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_cliente BIGINT NOT NULL UNIQUE
) ENGINE=InnoDB;

SELECT id FROM cliente ORDER BY id LIMIT 100000;

CREATE TEMPORARY TABLE tmp_pop_domicili (
    progressivo INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_domicilio BIGINT NOT NULL UNIQUE
) ENGINE=InnoDB;

SELECT id FROM domicilio ORDER BY id LIMIT 100000;

-- 3. Relazioni cliente-domicilio. Si prendono coppie distinte e si saltano
-- quelle già presenti; il LIMIT inserisce solo le righe ancora necessarie.
SELECT 100000 - LEAST(100000, COUNT(*)) INTO @pop_relazioni_mancanti
FROM domicili_cliente;

SET @pop_sql = '
    SELECT c.id_cliente, d.id_domicilio
    FROM tmp_pop_clienti AS c
    INNER JOIN tmp_pop_domicili AS d ON d.progressivo = c.progressivo
    LEFT JOIN domicili_cliente AS dc
      ON dc.id_cliente = c.id_cliente AND dc.id_domicilio = d.id_domicilio
    WHERE dc.id_cliente IS NULL
    ORDER BY c.progressivo
    LIMIT ?';
PREPARE pop_stmt FROM @pop_sql;
EXECUTE pop_stmt USING @pop_relazioni_mancanti;
DEALLOCATE PREPARE pop_stmt;

-- 4. Fatturazioni. I codici TEST-000001 ... TEST-100000 sono distinti;
-- si saltano quelli già usati, anche se le righe preesistenti hanno altri ID.
SELECT 100000 - LEAST(100000, COUNT(*)) INTO @pop_fatture_mancanti
FROM fatturazione;

SET @pop_sql = '
    SELECT CONCAT(''TEST-'', LPAD(n.n, 6, ''0'')),
           DATE_ADD(''2020-01-01'', INTERVAL MOD(n.n - 1, 1826) DAY),
           ROUND(50 + MOD(n.n * 17, 995000) / 100, 2),
           DATE_ADD(''2020-01-31'', INTERVAL MOD(n.n - 1, 1826) DAY),
           CASE MOD(n.n - 1, 3)
               WHEN 0 THEN ''Servizi''
               WHEN 1 THEN ''Prodotti''
               ELSE ''Abbonamento''
           END,
           d.id_domicilio
    FROM tmp_pop_numeri AS n
    INNER JOIN tmp_pop_domicili AS d ON d.progressivo = n.n
    LEFT JOIN fatturazione AS f
      ON f.codice = CONCAT(''TEST-'', LPAD(n.n, 6, ''0''))
    WHERE f.id IS NULL
    ORDER BY n.n
    LIMIT ?';
PREPARE pop_stmt FROM @pop_sql;
EXECUTE pop_stmt USING @pop_fatture_mancanti;
DEALLOCATE PREPARE pop_stmt;

CREATE TEMPORARY TABLE tmp_pop_fatture (
    progressivo INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_fatturazione BIGINT NOT NULL UNIQUE,
    data_emissione DATE NOT NULL
) ENGINE=InnoDB;

SELECT id, dataEmissione FROM fatturazione ORDER BY id LIMIT 100000;

-- 5. Pagamenti: una coppia distinta fattura-cliente per ogni progressivo;
-- si saltano le coppie già presenti. La data scelta è quella di emissione.
SELECT 100000 - LEAST(100000, COUNT(*)) INTO @pop_pagamenti_mancanti
FROM pagamento;

SET @pop_sql = '
    SELECT f.id_fatturazione, c.id_cliente, f.data_emissione
    FROM tmp_pop_fatture AS f
    INNER JOIN tmp_pop_clienti AS c ON c.progressivo = f.progressivo
    LEFT JOIN pagamento AS p
      ON p.id_fatturazione = f.id_fatturazione AND p.id_cliente = c.id_cliente
    WHERE p.id_fatturazione IS NULL
    ORDER BY f.progressivo
    LIMIT ?';
PREPARE pop_stmt FROM @pop_sql;
EXECUTE pop_stmt USING @pop_pagamenti_mancanti;
DEALLOCATE PREPARE pop_stmt;

COMMIT;

DROP TEMPORARY TABLE IF EXISTS tmp_pop_fatture;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_domicili;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_clienti;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_numeri;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_nomi;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_cognomi;
DROP TEMPORARY TABLE IF EXISTS tmp_pop_indirizzi;

-- Verifica finale: ogni conteggio deve essere almeno 100.000.
SELECT 'cliente' AS tabella, COUNT(*) AS numero_record FROM cliente
UNION ALL
SELECT 'domicilio', COUNT(*) FROM domicilio
UNION ALL
SELECT 'domicili_cliente', COUNT(*) FROM domicili_cliente
UNION ALL
SELECT 'fatturazione', COUNT(*) FROM fatturazione
UNION ALL
SELECT 'pagamento', COUNT(*) FROM pagamento;
